  ccxt::any parseFundingRate(ccxt::any contract,
                             ccxt::any market = ccxt::any{}) override {
    //
    // {
    //     "ticker_id":"ADA_PERP",
    //     "stock_currency":"ADA",
    //     "money_currency":"USDT",
    //     "last_price":"0.296708",
    //     "stock_volume":"7982130",
    //     "money_volume":"2345758.29189",
    //     "bid":"0.296608",
    //     "ask":"0.296758",
    //     "high":"0.298338",
    //     "low":"0.290171",
    //     "product_type":"Perpetual",
    //     "open_interest":"46533000",
    //     "index_price":"0.29659",
    //     "index_name":"Cardano",
    //     "index_currency":"ADA",
    //     "funding_rate":"0.0001",
    //     "next_funding_rate_timestamp":"1691193600000",
    //     "brackets":{
    //        "1":"0",
    //        "2":"0",
    //        "3":"0",
    //        "5":"0",
    //        "10":"0",
    //        "20":"0",
    //        "50":"-10000",
    //        "100":"-5000"
    //     },
    //     "max_leverage":"100"
    //  }
    //
    ccxt::any marketId = this->safeString(contract, std::string("ticker_id"));
    ccxt::any symbol = this->safeSymbol(marketId, market);
    ccxt::any markPrice = this->safeNumber(contract, std::string("markPrice"));
    ccxt::any indexPrice =
        this->safeNumber(contract, std::string("indexPrice"));
    ccxt::any interestRate =
        this->safeNumber(contract, std::string("interestRate"));
    ccxt::any fundingRate =
        this->safeNumber(contract, std::string("funding_rate"));
    ccxt::any fundingTime =
        this->safeInteger(contract, std::string("next_funding_rate_timestamp"));
    return ccxt::dict{
        {std::string("info"), contract},
        {std::string("symbol"), symbol},
        {std::string("markPrice"), markPrice},
        {std::string("indexPrice"), indexPrice},
        {std::string("interestRate"), interestRate},
        {std::string("timestamp"), ccxt::any{}},
        {std::string("datetime"), ccxt::any{}},
        {std::string("fundingRate"), fundingRate},
        {std::string("fundingTimestamp"), fundingTime},
        {std::string("fundingDatetime"), this->iso8601(fundingTime)},
        {std::string("nextFundingRate"), ccxt::any{}},
        {std::string("nextFundingTimestamp"), ccxt::any{}},
        {std::string("nextFundingDatetime"), ccxt::any{}},
        {std::string("previousFundingRate"), ccxt::any{}},
        {std::string("previousFundingTimestamp"), ccxt::any{}},
        {std::string("previousFundingDatetime"), ccxt::any{}},
        {std::string("interval"), ccxt::any{}},
    };
  }

  /**
   * @method
   * @name whitebit#fetchFundingHistory
   * @description fetch the history of funding payments paid and received on
   * this account
   * @see https://docs.whitebit.com/private/http-trade-v4/#funding-history
   * @param {string} [symbol] unified market symbol
   * @param {int} [since] the starting timestamp in milliseconds
   * @param {int} [limit] the number of entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch funding history
   * for
   * @returns {object[]} a list of [funding history structures]{@link
   * https://docs.ccxt.com/?id=funding-history-structure}
   */
  std::shared_future<ccxt::any> fetchFundingHistory(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingHistory() requires "
                                             "a symbol argument"))));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startDate"), since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("endDate"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any response = awaitValue(
                     this->v4PrivatePostCollateralAccountFundingHistory(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "records": [
                 //             {
                 //                 "market": "BTC_PERP",
                 //                 "fundingTime": "1708704000000",
                 //                 "fundingRate": "0.00017674",
                 //                 "fundingAmount": "-0.171053531892",
                 //                 "positionAmount": "0.019",
                 //                 "settlementPrice": "50938.2",
                 //                 "rateCalculatedTime": "1708675200000"
                 //             },
                 //         ],
                 //         "limit": 100,
                 //         "offset": 0
                 //     }
                 //
                 ccxt::any data = this->safeList(
                     response, std::string("records"), ccxt::list{});
                 return this->parseFundingHistories(data, market, since, limit);
               })
        .share();
  }

  virtual ccxt::any parseFundingHistory(ccxt::any contract,
                                        ccxt::any market = ccxt::any{}) {
    //
    //     {
    //         "market": "BTC_PERP",
    //         "fundingTime": "1708704000000",
    //         "fundingRate": "0.00017674",
    //         "fundingAmount": "-0.171053531892",
    //         "positionAmount": "0.019",
    //         "settlementPrice": "50938.2",
    //         "rateCalculatedTime": "1708675200000"
    //     }
    //
    ccxt::any marketId = this->safeString(contract, std::string("market"));
    ccxt::any timestamp =
        this->safeInteger(contract, std::string("fundingTime"));
    return ccxt::dict{
        {std::string("info"), contract},
        {std::string("symbol"),
         this->safeSymbol(marketId, market, ccxt::any{}, std::string("swap"))},
        {std::string("code"), ccxt::any{}},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("id"), ccxt::any{}},
        {std::string("amount"),
         this->safeNumber(contract, std::string("fundingAmount"))},
    };
  }

  virtual ccxt::any parseFundingHistories(ccxt::any contracts,
                                          ccxt::any market = ccxt::any{},
                                          ccxt::any since = ccxt::any{},
                                          ccxt::any limit = ccxt::any{}) {
    ccxt::any result = ccxt::list{};
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(contracts));
         postFixIncrement(i)) {
      ccxt::any contract = ::getValue(contracts, i);
      arrayPush(result, this->parseFundingHistory(contract, market));
    }
    ccxt::any sorted = this->sortBy(result, std::string("timestamp"));
    return this->filterBySinceLimit(sorted, since, limit);
  }

  /**
   * @method
   * @name whitebit#fetchDepositsWithdrawals
   * @description fetch history of deposits and withdrawals
   * @see
   * https://github.com/whitebit-exchange/api-docs/blob/main/pages/private/http-main-v4.md#get-depositwithdraw-history
   * @param {string} [code] unified currency code for the currency of the
   * deposit/withdrawals, default is undefined
   * @param {int} [since] timestamp in ms of the earliest deposit/withdrawal,
   * default is undefined
   * @param {int} [limit] max number of deposit/withdrawals to return, default =
   * 50, Min: 1, Max: 100
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   *
   * EXCHANGE SPECIFIC PARAMETERS
   * @param {number} [params.transactionMethod] Method. Example: 1 to display
   * deposits / 2 to display withdraws. Do not send this parameter in order to
   * receive both deposits and withdraws.
   * @param {string} [params.address] Can be used for filtering transactions by
   * specific address or memo.
   * @param {string[]} [params.addresses] Can be used for filtering transactions
   * by specific addresses or memos (max: 20).
   * @param {string} [params.uniqueId] Can be used for filtering transactions by
   * specific unique id
   * @param {int} [params.offset] If you want the request to return entries
   * starting from a particular line, you can use OFFSET clause to tell it where
   * it should start. Default: 0, Min: 0, Max: 10000
   * @param {string[]} [params.status] Can be used for filtering transactions by
   * status codes. Caution: You must use this parameter with appropriate
   * transactionMethod and use valid status codes for this method. You can find
   * them below. Example: "status": [3,7]
   * @returns {object} a list of [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any> fetchDepositsWithdrawals(
      ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any request = ccxt::dict{};
                        ccxt::any currency = ccxt::any{};
                        if (isTrue(!isEqual(code, ccxt::any{}))) {
                          currency = this->currency(code);
                          ::setValue(request, std::string("ticker"),
                                     ::getValue(currency, std::string("id")));
                        }
                        if (isTrue(!isEqual(limit, ccxt::any{}))) {
                          ::setValue(request, std::string("limit"),
                                     limit); // default 1000
                        }
                        ccxt::any response =
                            awaitValue(this->v4PrivatePostMainAccountHistory(
                                this->extend(request, params)));
                        //
                        //    {
                        //        "limit": 100,
                        //        "offset": 0,
                        //        "records": [
                        //            {
                        //                "address":
                        //                "3ApEASLcrQtZpg1TsssFgYF5V5YQJAKvuE",
                        //                // deposit address "uniqueId": null,
                        //                // unique Id of deposit "createdAt":
                        //                1593437922, // timestamp of deposit
                        //                "currency": "Bitcoin", // deposit
                        //                currency "ticker": "BTC", // deposit
                        //                currency ticker "method": 1, // called
                        //                method 1 - deposit, 2 - withdraw
                        //                "amount": "0.0006", // amount of
                        //                deposit "description": "", // deposit
                        //                description "memo": "", // deposit
                        //                memo "fee": "0", // deposit fee
                        //                "status": 15, // transactions status
                        //                "network": null, // if currency is
                        //                multinetwork "transactionHash":
                        //                "a275a514013e4e0f927fd0d1bed215e7f6f2c4c6ce762836fe135ec22529d886",
                        //                // deposit transaction hash
                        //                "transactionId":
                        //                "5e112b38-9652-11ed-a1eb-0242ac120002",
                        //                // transaction id "details": {
                        //                    "partial": { // details about
                        //                    partially successful withdrawals
                        //                        "requestAmount": "50000", //
                        //                        requested withdrawal amount
                        //                        "processedAmount": "39000", //
                        //                        processed withdrawal amount
                        //                        "processedFee": "273", // fee
                        //                        for processed withdrawal
                        //                        amount "normalizeTransaction":
                        //                        "" // deposit id
                        //                    }
                        //                },
                        //                "confirmations": { // if transaction
                        //                status == 15 (Pending) you can see
                        //                this object
                        //                    "actual": 1, // current block
                        //                    confirmations "required": 2 //
                        //                    required block confirmation for
                        //                    successful deposit
                        //                }
                        //            },
                        //            {...},
                        //        ],
                        //        "total": 300 // total number of  transactions,
                        //        use this for calculating ‘limit’ and ‘offset'
                        //    }
                        //
                        ccxt::any records =
                            this->safeList(response, std::string("records"));
                        ccxt::any recordsList = ccxt::list{};
                        if (isTrue(!isEqual(records, ccxt::any{}))) {
                          recordsList = records;
                        }
                        return this->parseTransactions(recordsList, currency,
                                                       since, limit);
                      })
        .share();
  }

